* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; color: var(--text); background: var(--bg); }

/* Header */
header { background: var(--header-bg); color: var(--header-text); border-bottom: 1px solid rgba(255,255,255,0.08); }
.header-row { display: flex; align-items: center; flex-wrap: nowrap; max-width: 1400px; margin: 0 auto; padding: 0 1rem; }
.nav-brand, .nav-brand:link, .nav-brand:visited { color: var(--header-text); text-decoration: none; font-weight: 600; font-size: 1rem; display: flex; align-items: center; gap: 0.5rem; white-space: nowrap; padding: 0.6rem 0; margin-left: auto; }
.nav-brand:hover { color: var(--header-text); text-decoration: none; }
.ze-logo { width: 28px; height: 28px; max-width: 28px; max-height: 28px; object-fit: contain; flex-shrink: 0; }

/* Theme toggle */
.theme-toggle { background: none; border: none; color: var(--header-text); font-size: 1.2rem; cursor: pointer; padding: 0.4rem; opacity: 0.6; transition: opacity 0.15s; }
.theme-toggle:hover { opacity: 1; }

/* Tab navigation -- inline with brand */
.tab-bar { display: flex; gap: 0; }
.tab-bar a, .tab-bar a:link, .tab-bar a:visited { color: var(--header-text); text-decoration: none; font-size: 0.85rem; padding: 0.7rem 0.9rem; opacity: 0.6; border-bottom: 2px solid transparent; transition: opacity 0.15s, border-color 0.15s; }
.tab-bar a:hover { opacity: 1; }
.tab-bar a.tab-active { opacity: 1; border-bottom-color: var(--btn-bg); font-weight: 600; }

/* Main content */
main { max-width: 1400px; margin: 1.5rem auto; padding: 0 1rem; }
h1 { margin-bottom: 1rem; color: var(--heading); font-size: 1.3rem; }
h2 { margin: 0 0 0.75rem; color: var(--heading); font-size: 1.2rem; }

/* Search form -- all filters visible, stackable */
.search-form { margin-bottom: 1.5rem; }
.search-row { display: flex; gap: 0.75rem; align-items: flex-end; flex-wrap: wrap; }
.search-field { display: flex; flex-direction: column; gap: 0.25rem; }
.search-field label { font-weight: 500; font-size: 0.8rem; color: var(--th-text); text-transform: uppercase; letter-spacing: 0.03em; }
.search-field input, .search-field select { padding: 0.45rem 0.6rem; border: 1px solid var(--input-border); border-radius: 4px; font-size: 0.9rem; background: var(--input-bg); color: var(--input-text); }
.search-field input { min-width: 180px; }
.search-field select { min-width: 120px; }
.search-field-narrow select { min-width: 130px; }
.search-field-btn button { padding: 0.45rem 1.2rem; background: var(--btn-bg); color: #fff; border: none; border-radius: 4px; cursor: pointer; font-size: 0.9rem; font-weight: 500; }
.search-field-btn button:hover { background: var(--btn-hover); }

/* Tables */
table { width: 100%; border-collapse: collapse; background: var(--table-bg); border-radius: 6px; overflow: hidden; box-shadow: 0 1px 3px var(--shadow); }
thead { background: var(--table-head); }
th { padding: 0.6rem 0.8rem; text-align: left; font-size: 0.8rem; font-weight: 600; color: var(--th-text); text-transform: uppercase; letter-spacing: 0.03em; border-bottom: 2px solid var(--table-border); }
td { padding: 0.5rem 0.8rem; font-size: 0.85rem; border-bottom: 1px solid var(--table-row-border); }
tbody tr:hover { background: var(--table-hover); cursor: pointer; }
tbody tr.best-route { background: var(--best-bg); }

/* Peer state colors */
.state-up .state, .peer-info-state.state-up { color: var(--state-up); font-weight: 600; }
.state-down .state, .peer-info-state.state-down { color: var(--state-down); font-weight: 600; }
.state-unknown .state, .peer-info-state.state-unknown { color: var(--state-unknown); }

/* Peer info banner */
.peer-info { display: flex; gap: 1.5rem; align-items: center; margin-bottom: 1rem; padding: 0.6rem 1rem; background: var(--peer-info-bg); border-radius: 6px; box-shadow: 0 1px 3px var(--shadow); font-size: 0.9rem; }
.peer-info span { white-space: nowrap; }
.peer-info-desc { color: var(--th-text); font-style: italic; }
.peer-info-count { font-weight: 600; }
.peer-info-group, .peer-info-state-changed, .peer-info-connections-dropped { color: var(--th-text); }
.peer-info .peer-info-last-error { color: var(--state-down); white-space: normal; }
.btn-download { margin-left: auto; padding: 0.3rem 0.8rem; background: var(--btn-bg); color: #fff; border-radius: 4px; font-size: 0.8rem; text-decoration: none; white-space: nowrap; }
.btn-download:hover { background: var(--btn-hover); color: #fff; text-decoration: none; }

/* Peer detail area -- inserted below peer table */
.peer-detail-area { margin-top: 1.5rem; position: relative; min-height: 0; transition: opacity 0.15s; }
.peer-detail-area.htmx-request { min-height: 3rem; opacity: 0.5; }
.peer-detail-area.htmx-request::after { content: ""; position: absolute; top: 1rem; left: 50%; width: 1.2rem; height: 1.2rem; margin-left: -0.6rem; border: 2px solid var(--table-border); border-top-color: var(--btn-bg); border-radius: 50%; animation: spin 0.6s linear infinite; }
.peer-detail-area:empty.htmx-request { opacity: 1; }

/* Route detail panel */
.detail-panel { padding: 1rem; background: var(--detail-bg); border-left: 3px solid var(--detail-border); }
.detail-panel h3 { margin-bottom: 0.5rem; font-size: 0.95rem; }
.detail-panel dl { display: grid; grid-template-columns: 160px 1fr; gap: 0.3rem; font-size: 0.85rem; }
.detail-panel dt { font-weight: 600; color: var(--detail-dt); }
.detail-panel dd { color: var(--detail-dd); word-break: break-all; }
.route-detail { background: var(--detail-bg); }

/* Help page */
.help-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 1rem; margin-bottom: 1.5rem; }
.help-card { background: var(--table-bg); border-radius: 6px; padding: 1.2rem; box-shadow: 0 1px 3px var(--shadow); cursor: pointer; transition: box-shadow 0.15s; }
.help-card:hover { box-shadow: 0 2px 8px var(--shadow); }
.help-card h3 { margin: 0.5rem 0 0.3rem; font-size: 0.95rem; color: var(--heading); }
.help-card p { font-size: 0.85rem; line-height: 1.5; color: var(--text); margin: 0; }
.help-icon { font-size: 1.6rem; }
.help-card.active { border-color: var(--btn-bg); box-shadow: 0 2px 8px var(--shadow); border-left: 3px solid var(--btn-bg); }
.help-detail-panel { display: none; margin-top: 1rem; padding: 1.2rem; background: var(--table-bg); border-radius: 6px; border-left: 3px solid var(--btn-bg); box-shadow: 0 1px 3px var(--shadow); }
.help-detail-panel.visible { display: block; }
.help-detail-panel p { font-size: 0.85rem; line-height: 1.5; margin-bottom: 0.4rem; }
.help-detail-panel code { background: var(--table-head); padding: 0.1rem 0.35rem; border-radius: 3px; font-size: 0.85em; }
.help-section { margin-bottom: 1.5rem; }
.help-section h2 { margin-top: 0; }
.help-section p { margin-bottom: 0.5rem; line-height: 1.5; font-size: 0.9rem; }
.help-section code { background: var(--table-head); padding: 0.1rem 0.35rem; border-radius: 3px; font-size: 0.85em; }
.help-api-table { margin-top: 0.5rem; }
.help-api-table code { background: var(--table-head); padding: 0.1rem 0.35rem; border-radius: 3px; font-size: 0.85em; }

/* Graph */
.graph-controls { margin: 1rem 0 0.5rem; display: flex; gap: 0.5rem; }
.graph-mode-btn { padding: 0.3rem 0.8rem; background: var(--table-bg); color: var(--text); border: 1px solid var(--table-border); border-radius: 4px; cursor: pointer; font-size: 0.8rem; font-family: monospace; }
.graph-mode-btn:hover { background: var(--btn-hover); color: #fff; }
.graph-mode-btn.active { background: var(--btn-bg); color: #fff; border-color: var(--btn-bg); }
#graph-container { margin: 0.5rem 0 1rem; overflow-x: auto; }
#graph-container svg { max-width: 100%; height: auto; }

/* ASN name */
.asn-name { color: var(--th-text); font-size: 0.8rem; margin-left: 0.3rem; }
.next-hop-name { color: var(--th-text); font-size: 0.8rem; }
td.state-changed, td.connections-dropped, .route-age { white-space: nowrap; font-variant-numeric: tabular-nums; }
td.peer-description { color: var(--th-text); max-width: 24rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* BMP peers section */
.bmp-peers-table { border-left: 3px solid var(--state-unknown); }

/* Error and empty states */
.error-banner { padding: 0.8rem 1rem; background: var(--error-bg); border: 1px solid var(--error-border); border-radius: 6px; color: var(--error-text); margin-bottom: 1rem; font-weight: 500; }
/* Engine failure reported by the peer stream. One unnamed message carries the
   whole table body, so the reason arrives as the body's only row. */
.stream-error td { background: var(--error-bg); color: var(--error-text); font-weight: 500; text-align: center; }
/* Refused request. The server answers this fragment (internal/core/errorfragment)
   when a handler refuses an htmx request, and htmx swaps it into the target. */
.error-fragment { padding: 0.8rem 1rem; background: var(--error-bg); border: 1px solid var(--error-border); border-radius: 6px; color: var(--error-text); margin-bottom: 1rem; display: flex; align-items: baseline; gap: 0.5rem; }
.error-fragment-reason { font-weight: 700; white-space: nowrap; }
/* An operator error is several lines (what went wrong, why, the fix: opererr),
   so every surface that shows one keeps its line breaks, as the web UI's do:
   the banner, the refusal fragment and the peer stream's error row. */
.error-banner,
.error-fragment-message,
.stream-error td { white-space: pre-wrap; }
.empty-state { padding: 2rem; text-align: center; color: var(--state-unknown); font-style: italic; }

/* HTMX loading */
.htmx-indicator { display: none; margin-left: 0.5rem; }
.htmx-request .htmx-indicator, .htmx-request.htmx-indicator { display: inline-block; }
.spinner { display: inline-block; width: 1rem; height: 1rem; border: 2px solid var(--table-border); border-top-color: var(--btn-bg); border-radius: 50%; animation: spin 0.6s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

/* Result count */
.result-count { color: var(--th-text); font-size: 0.9rem; margin-bottom: 0.5rem; }

/* Responsive */
@media (max-width: 768px) {
  .search-row { flex-direction: column; }
  .search-field input, .search-field select { min-width: auto; width: 100%; }
  table { font-size: 0.8rem; }
  th, td { padding: 0.4rem; }
  .tab-bar a { padding: 0.5rem 0.6rem; font-size: 0.8rem; }
}

(function(){
  var t = localStorage.getItem('lg-theme');
  if (t) document.documentElement.setAttribute('data-theme', t);
})();

document.addEventListener('DOMContentLoaded', function() {
  // Tab active state -- update on HTMX navigation
  document.querySelectorAll('.tab-bar a').forEach(function(tab) {
    tab.addEventListener('click', function() {
      document.querySelectorAll('.tab-bar a').forEach(function(t) { t.classList.remove('tab-active'); });
      this.classList.add('tab-active');
    });
  });

  // Graph mode persistence -- restore from localStorage after HTMX swaps in new content.
  function applyGraphMode() {
    var mode = localStorage.getItem('lg-graph-mode') || 'aspath';
    var btns = document.querySelectorAll('.graph-mode-btn');
    if (btns.length === 0) return;
    btns.forEach(function(b) {
      b.classList.toggle('active', b.getAttribute('data-mode') === mode);
    });
    var container = document.getElementById('graph-container');
    if (container && container.getAttribute('data-loaded') !== 'true') {
      var prefix = btns[0].getAttribute('data-prefix');
      container.setAttribute('data-loaded', 'true');
      htmx.ajax('GET', '/lg/graph?prefix=' + encodeURIComponent(prefix) + '&mode=' + mode, {target: container, swap: 'innerHTML'});
    }
  }

  // Save mode on click.
  document.addEventListener('click', function(e) {
    var btn = e.target.closest('.graph-mode-btn');
    if (!btn) return;
    localStorage.setItem('lg-graph-mode', btn.getAttribute('data-mode'));
  });

  // Apply after HTMX swaps (search results, navigation).
  document.addEventListener('htmx:after:settle', applyGraphMode);
  applyGraphMode();

  // Help card expand/collapse -- detail shown below cards.
  document.addEventListener('click', function(e) {
    var card = e.target.closest('.help-card');
    if (!card) return;
    var key = card.getAttribute('data-help');
    if (!key) return;
    var panel = document.getElementById('help-detail');
    var tmpl = document.getElementById('help-' + key);
    if (!panel || !tmpl) return;

    // Toggle off if clicking the same card.
    if (card.classList.contains('active')) {
      card.classList.remove('active');
      panel.classList.remove('visible');
      while (panel.firstChild) panel.removeChild(panel.firstChild);
      return;
    }

    // Deactivate all cards, activate clicked one.
    document.querySelectorAll('.help-card').forEach(function(c) { c.classList.remove('active'); });
    card.classList.add('active');
    while (panel.firstChild) panel.removeChild(panel.firstChild);
    panel.appendChild(tmpl.content.cloneNode(true));
    panel.classList.add('visible');
  });

  var btn = document.getElementById('theme-toggle');
  if (btn) btn.addEventListener('click', function() {
    var h = document.documentElement;
    var c = h.getAttribute('data-theme');
    var n = c === 'dark' ? 'light' : c === 'light' ? 'dark'
      : window.matchMedia('(prefers-color-scheme:dark)').matches ? 'light' : 'dark';
    h.setAttribute('data-theme', n);
    localStorage.setItem('lg-theme', n);
  });
});

/* Ze looking glass graph mode -- marks the graph-mode button the operator
   pressed. The buttons carry data-mode and the HTMX attributes that fetch the
   drawing, and this file carries the class change.

   It is external because the looking glass answers every page with
   `default-src 'self'` and no script-src beside it (setSecurityHeaders,
   server.go). A browser refuses an inline handler under that header, so the
   onclick this replaced ran in no browser and the pressed button never looked
   pressed.

   The listener sits on the document, so it survives the HTMX swap that
   replaces #results with a new result panel and its buttons. */
(function(){
  'use strict';
  document.addEventListener('click', function(e) {
    var btn = e.target.closest ? e.target.closest('.graph-mode-btn') : null;
    if (!btn) return;

    var group = btn.closest('.graph-controls');
    if (!group) return;

    Array.prototype.forEach.call(group.querySelectorAll('.graph-mode-btn'), function(b) {
      b.classList.remove('active');
    });
    btn.classList.add('active');
  });
})();
